    yearMonth: '2026-11',
    img: '/static/picture/gmvPNmEcT.jpg',
    summary: "物理AI正加速渗透现实世界，面对可靠性挑战，基础设施需提供可验证的物理经验，同时聚焦底层需求，形成全面的交付路径。",
    content: [
      "随着人形机器人加速进入生产线，物理AI正步入现实。贾维斯的设想如今成为现实，但其可靠性成为关键。以Figure 02为例，其在宝马美国工厂的实训展示了对可靠性极高的需求，这要求基础设施不仅提供算力，还需保障数据验证、标准确定及部署效率。",
      "物理AI的基础设施需满足多样化的计算需求，而单一提供算力已难以满足需求。围绕数据生产、评测标准和工程部署，物理AI基础设施正在分化出不同的路径。这些路径虽各有优势，但底层需求的共通性正促使公共底座的形成，减少试错成本，成为必选项，助力物理AI更稳定地落地。",
      "对于企业主而言，应聚焦于底层需求，利用已有公共底座，加速物理AI的开发和应用。随着场景需求的不断变化，物理AI基础设施的集中化趋势将愈发明显，为未来科技入口奠定坚实基础。"
]
