      "何小鹏在2026小鹏科技日上展望了机器人产业的未来，认为其长期前景极其乐观，预期将成为全球最大的产业，超越当前规模庞大的汽车产业。然而，当前机器人市场仍面临销量小、商业模型难以跑通的挑战，仅几万台的规模远不足以支撑投资回报。这需要企业逐步推出更高阶的机器人产品，以满足消费者的多种需求。",
