      "根据二手交易平台得物及线下数码商家的信息，iPhone Duo 256GB版本的价格已从首发价的16000元降至14615元，某些渠道甚至低至14500元，与18 Pro Max相比，保值率明显较低。这意味着，对于那些期望通过转手获利的黄牛而言，iPhone Duo的价格下滑速度之快，远超他们的预期。",
