    id: '316',
    title: "蔚来AI原生组织架构：推动企业数字化转型",
    category: '公司新闻',
    date: '2026-11-25',
    day: '25',
    yearMonth: '2026-11',
    img: '/static/picture/1752658141724106.jpg',
    summary: "蔚来创始人李斌公布了AI原生组织架构，涵盖六层结构，大幅提升研发和供应链效率，未来将深化AI在企业经营中的应用。",
    content: [
      "蔚来创始人李斌近日宣布推出AI原生组织架构，该架构下蔚来已上线超过7500个智能Agent，累计运行超290万个实例，涉及研发、供应链及用户服务等多个业务环节。这标志着蔚来正加速向AI化转型，以AI作为核心驱动力，优化企业流程和决策机制。",
      "蔚来AI原生组织架构包括AI基础设施、CBU设置、大模型、领域Agent、业务Agent及企业BU经营层，各层协同工作，底层基础设施连接用户、车辆等关键要素，业务Agent则针对特定场景，通过多个Agent的协同完成任务。通过将超过1800个研发项目纳入AI管理，蔚来实现了研发人效提升43%，综合研发效率提升35%，供应链合作伙伴订单交付达成率也提升至99%。",
      "在用户服务方面，超过9750名Fellow已能调用相关Agent，提升了服务质量。蔚来计划进一步优化AI原生组织，让AI更深度地参与到企业经营和业务决策中，预计将在未来带来更多效率提升和业务优化的机会。",
      "蔚来通过构建AI原生组织架构，不仅提升了内部运作效率，也为行业展示了AI在企业数字化转型中的巨大潜力。"
]
