    id: '313',
    title: "亚马逊75亿美元收购Decart优化栈，推动AI技术革新",
    category: '建站知识',
    date: '2026-11-25',
    day: '25',
    yearMonth: '2026-11',
    img: '/static/picture/1752658141724106.jpg',
    summary: "亚马逊斥资75亿美元收购Decart的专有技术，三位创始人加入亚马逊团队，将助力公司提高芯片效率与降低成本，进一步推动AI技术发展。",
    content: [
      "亚马逊近期以75亿美元的价格收购了Decart的优化栈技术，这笔交易并未涉及整家公司，而是Decart背后的专有技术。Decart联合创始人Dean Leitersdorf、Moshe Shalev和Orian Leitersdorf以及团队成员将加入亚马逊，承诺长期留任。Decart以其交互式实时世界模型Oasis 3和AI视频生成工具闻名，此前已与亚马逊Trainium芯片建立了合作关系，展示了在自研芯片上的速度和成本优势。",
      "亚马逊负责基础AI模型、自研芯片和量子计算的高级副总裁Peter DeSantis认为，提高每颗芯片的效率意味着更好的训练、强化学习和推理，客户将能以更低的成本获得更优质的模型。此次收购不仅代表亚马逊在AI技术上的重大突破，也展示了其在自研芯片领域的领先实力。不过，公告中并没有明确提到Decart的AI模型和现有客户关系的处置问题。",
      "Decart的估值在短短半年内迅速上涨，今年5月融得3亿美元，估值达40亿美元，Anthropic曾考虑以约60亿美元收购，但到了9月便退出了。此次亚马逊的收购价格已接近75亿美元，显示出其在AI领域的高度关注和投入。此次收购不仅加强了亚马逊在AI领域的竞争力，也有助于促进整个行业的技术革新。",
      "通过此次收购，亚马逊不仅获得了Decart的技术和团队，还进一步巩固了其在AI领域的领先地位，加速了公司数字化转型的步伐。"
]
