    category: '建站知识',
    date: '2026-11-25',
    day: '25',
    yearMonth: '2026-11',
    img: '/static/picture/1752658217587676.jpg',
    summary: "谷歌Chrome开发者团队在X平台发文支持Mozilla，认为苹果对第三方浏览器引擎的限制形同虚设，呼吁欧盟向苹果施压。",
    content: [
      "近日，谷歌Chrome开发者团队在X平台上发文，表达了对Mozilla的支持。此前，Mozilla等企业曾联名向欧盟委员会投诉苹果对iOS浏览器引擎的限制，要求苹果从2024年初开始允许欧盟地区的iOS设备使用第三方浏览器引擎。然而，由于苹果设置的种种限制，至今没有任何一家厂商能够从WebKit迁移到其他引擎，这使得所谓的“选择”形同虚设。",
      "Chrome开发者团队指出，苹果规定浏览器厂商必须单独开发新浏览器并分发全新App，而不能直接通过更新现有浏览器的方式替换内核。这一规定使得像Mozilla这样的企业难以实现跨引擎迁移，不得不面临重新开发和分发新应用的挑战。Chrome开发者团队强调，这种做法不仅阻碍了市场竞争，还增加了用户获取浏览器的难度。",
      "面对这一情况，谷歌Chrome开发者团队表示，苹果所谓的“选择”只是表面上的政策，实际上却限制了浏览器厂商的灵活性和创新性。他们呼吁欧盟委员会继续施压苹果，确保iOS平台能够支持第三方浏览器引擎，从而促进互联网生态的健康发展。",
      "综上所述，开发者们希望通过支持Mozilla等企业，促使苹果改变其限制政策，以实现更公平、开放的互联网环境。"
]
