    category: '行业新闻',
    date: '2026-11-23',
    day: '23',
    yearMonth: '2026-11',
    img: '/static/picture/1752658141724106.jpg',
    summary: "法国人工智能企业Mistral AI宣布在新加坡设立亚太总部，重点开发公共部门、高科技制造和机器人领域的主权AI模型，与新加坡内政科技局合作开发的Phoenix项目已有成果。",
    content: [
      "法国人工智能企业Mistral AI宣布在新加坡设立亚太总部，这标志着其在全球市场布局中的重要一步。Mistral AI已在新加坡开展业务，并与新加坡内政科技局（HTX）合作开发了Phoenix项目，旨在为新加坡政府自主研发大语言模型。这项合作不仅加快了更安全、更智能的AI解决方案的开发，还提升了公共安全人员的工作效率。",
      "Mistral AI成立于2023年4月，其三位联合创始人均为欧洲出身的AI研究员，拥有丰富的AI研究背景，如曾担任谷歌DeepMind高级研究科学家的首席执行官Arthur Mensch。Mistral AI凭借其开放权重的路线，被誉为“欧洲版OpenAI”。其融资情况也非常亮眼，短短一年多时间里完成了多轮融资，总估值升至210亿欧元。",
      "Mistral AI设立亚太总部的重点在于公共部门、高科技制造和机器人三大领域，特别是机器人领域的智能模型Robostral Navigate，能够依靠单个RGB相机自主导航复杂环境。该公司强调“主权AI”，即组织自行掌控AI的运作方式，包括流程知识、知识产权、数据、产品开发等关键环节。",
      "此次设立亚太总部，Mistral AI将充分利用新加坡作为科技中心的优势，进一步推动主权AI的研发，为全球科技发展贡献力量。"
]
