      "这款适配器在日本市场可使用Docomo、au和SoftBank的网络，采用预付费流量套餐，理论下载速度最高可达150Mbps，上传速度最高50Mbps，最多支持8台设备同时连接。对于需要在不同地区使用Switch 2的用户，Kausmedia也提供了覆盖美国、加拿大和欧盟等地的国际预付费流量套餐，不过这部分用户需额外购买国际套餐。适配器小巧轻便，尺寸为51×54×18mm，重量约50g，便于携带。",
