      "达里奥和丹妮拉都怀揣着改善世界的梦想。达里奥在读博士期间因父亲去世而对医学产生兴趣，丹妮拉则选择人文学科。两人对有效利他主义的共同兴趣，促使他们在2013年共同搬入旧金山的一栋公寓，开始探讨科技、慈善和社会进步。他们的创业故事充满创新与独特性，如设计Power Smoothie饮品，旨在减少动物痛苦。",
      "Anthropic的组织文化与发展理念源自这对兄妹的独特经历。他们坚持独特的工作方式，如在圣克鲁斯山脉的花园中为员工提供特别活动，以此增强团队凝聚力。这种创新的工作环境和独特的文化理念，使得Anthropic不同于其他科技公司，成为AI领域的佼佼者。",
