    content: [
      "Anthropic近期在纳斯达克上市，打破了SpaceX的IPO募资纪录，募集总额达到935亿美元。亚马逊和谷歌作为最大机构投资者，总计持股28%，所持股份价值约3300亿美元。两家科技巨头通过多年持续的投资和参与Anthropic的IPO，不仅获得了巨额回报，还与Anthropic建立了重要的云计算合作关系，预示着AI科技领域的新发展。",
      "亚马逊和谷歌投资Anthropic始于2023年，当时Anthropic仅有约160名员工。亚马逊累计投入80亿美元，谷歌则投入了200亿美元。根据IPO收盘价，亚马逊持有的约19.4亿股价值1720亿美元，谷歌持有的约17.7亿股价值1580亿美元。此外，两家公司还同意将Anthropic作为其关键工作负载的主要云服务提供商，承诺在未来多年分别向亚马逊和谷歌支付至少1100亿美元和1213亿美元。",
      "除了股权投资和云计算合作关系，亚马逊和谷歌还通过Anthropic的IPO获得了丰厚回报。光速创投和Iconiq等风险投资机构也因持股获得了巨大收益，显示了当前AI科技领域的投资热情和巨大潜力。此次IPO不仅为两家科技巨头带来了资金，也为Anthropic的AI技术发展提供了强有力的支持。",
      "亚马逊和谷歌通过Anthropic的IPO和云计算合作，展示了科技巨头在AI领域的战略布局，对推动AI技术发展和企业数字化转型具有重要意义。"
]
